(() => {
  'use strict';
  const input=document.getElementById('tool-search'),cards=[...document.querySelectorAll('.tool-card')],sections=[...document.querySelectorAll('.tool-section')],count=document.getElementById('result-count'),empty=document.getElementById('empty');if(!input)return;
  const tags={har:'网站慢 页面慢 网页慢 请求 网络性能',logs:'报错 错误 找日志 排障',assets:'查库存 借电脑 借还 领用 盘点 耗材',poster:'做通知 发通知 宣传 海报 邀请',display:'大屏 公告 会议议程 轮播',recorder:'录会议 录教程 屏幕录制',video:'剪视频 截取视频',audio:'剪音频 拼声音',subtitles:'加字幕 章节 校对字幕',redact:'隐私 打码 马赛克',sqlite:'数据库 查数据 sql',projects:'项目 进度 排期 工时',kanban:'待办 提醒 工作任务',survey:'调查 问卷 满意度 评分 投票 本机汇总',rack:'机柜 机房 三维 3d',ipam:'地址重复 ip冲突 网段',commands:'命令 怎么配置 linux 华为 思科 华三',nginx:'反向代理 网站发布 配置服务器',convert:'转格式 转码 压缩',wireless:'wifi 无线 信号 ap',power:'电量 电池 ups 空调 制冷',recovery:'恢复 备份 丢数据',lottery:'抽奖 年会', 'image-editor':'修图 图层 编辑图片', 'epub-reader':'看书 阅读 小说'};
  const slug=c=>new URL(c.href).pathname.split('/').filter(Boolean).pop();const valid=new Set(cards.map(slug));
  const read=k=>{try{const v=JSON.parse(localStorage.getItem(k)||'[]');return Array.isArray(v)?v.filter(x=>valid.has(x)):[];}catch{return [];}};
  let favorites=new Set(read('yj-tool-favorites-v1')),mode='all';
  const chips=document.createElement('div');chips.className='wb-chips';for(const [value,label] of [['all','全部工具'],['favorite','我的收藏'],['recent','最近使用']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.mode=value;b.onclick=()=>{mode=value;update();};chips.append(b);}
  const storage=document.createElement('a');storage.href='data/index.html';storage.textContent='备份与存储管理 ↗';storage.style.alignSelf='center';chips.append(storage);document.querySelector('.finder').after(chips);
  for(const card of cards){const id=slug(card),slot=document.createElement('div');slot.className='tool-card-slot';card.before(slot);slot.append(card);const b=document.createElement('button');b.className='wb-favorite';b.type='button';b.setAttribute('aria-label','收藏'+card.querySelector('h3').textContent);b.onclick=e=>{e.preventDefault();e.stopPropagation();if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem('yj-tool-favorites-v1',JSON.stringify([...favorites]));}catch{}update();};slot.append(b);card.addEventListener('click',()=>{try{localStorage.setItem('yj-tool-recent-v1',JSON.stringify([id,...read('yj-tool-recent-v1').filter(x=>x!==id)].slice(0,10)));}catch{}});}
  function update(){const q=input.value.trim().toLocaleLowerCase(),terms=q.split(/\s+/).filter(Boolean),recent=read('yj-tool-recent-v1');let n=0;for(const card of cards){const id=slug(card),text=(card.querySelector('h3').textContent+' '+card.querySelector('p').textContent+' '+(tags[id]||'')).toLocaleLowerCase(),show=terms.every(t=>text.includes(t))&&(mode==='all'||mode==='favorite'&&favorites.has(id)||mode==='recent'&&recent.includes(id));card.hidden=!show;card.parentElement.hidden=!show;if(show)n++;const b=card.parentElement.querySelector('.wb-favorite');b.textContent=favorites.has(id)?'★':'☆';b.setAttribute('aria-pressed',String(favorites.has(id)));}for(const section of sections)section.hidden=![...section.querySelectorAll('.tool-card')].some(c=>!c.hidden);for(const b of chips.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.mode===mode));count.textContent=`${mode==='favorite'?'收藏':mode==='recent'?'最近使用':'找到'} ${n} 个工具`;empty.hidden=n!==0;empty.textContent=mode==='favorite'&&!q?'还没有收藏，点击工具卡片右上角的 ☆ 即可收藏。':mode==='recent'&&!q?'打开一个工具后，这里会出现使用记录。':'没有找到匹配工具，试试“网站慢”“做通知”“查库存”。';}
  input.placeholder='搜索名称或需求：网站慢、做通知、查库存…';input.addEventListener('input',update);update();
})();
